import re
import secrets

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._users = {}          # username -> password
        self._tokens = {}         # token -> (username, created)
        self._docs = {}           # doc_id -> doc dict (live only)
        self._doc_seq = {}        # doc_id -> sequence number
        self._user_docs = {}      # username -> {seq: doc_id} (insertion = creation order)
        self._next_doc = 0
        self._cursors = {}        # cursor -> (username, last_seq)
        self._attempts = {}       # (username, key) -> {"amount", "payment"}
        self._payments = {}       # username -> [payment]
        self._next_payment = 0

    # ---- helpers ----
    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        return None

    @staticmethod
    def _valid_doc_fields(title, content):
        if not isinstance(title, str) or not isinstance(content, str):
            return False
        return 1 <= len(title) <= 200 and len(content) <= 100000

    def _live_docs(self, user):
        d = self._user_docs.get(user, {})
        return [(seq, self._docs[did]) for seq, did in sorted(d.items())]

    # ---- auth ----
    def register(self, username, password):
        if not isinstance(username, str) or not isinstance(password, str):
            return 400, None
        if not _USERNAME_RE.fullmatch(username) or len(password) < 8:
            return 400, None
        if username in self._users:
            return 409, None
        self._users[username] = password
        return 201, None

    def login(self, username, password):
        if not isinstance(username, str) or not isinstance(password, str):
            return 401, None
        if self._users.get(username) != password:
            return 401, None
        token = secrets.token_hex(16)
        while token in self._tokens:
            token = secrets.token_hex(16)
        self._tokens[token] = (username, self._clock.now())
        return 200, {"token": token}

    def logout(self, token):
        if self._auth(token) is None:
            return 401, None
        del self._tokens[token]
        return 204, None

    # ---- documents ----
    def create_document(self, token, title, content):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not self._valid_doc_fields(title, content):
            return 400, None
        self._next_doc += 1
        seq = self._next_doc
        doc_id = "doc-%d" % seq
        self._docs[doc_id] = {
            "id": doc_id, "owner": user, "title": title,
            "content": content, "created_at": self._clock.now(),
        }
        self._doc_seq[doc_id] = seq
        self._user_docs.setdefault(user, {})[seq] = doc_id
        return 201, {"id": doc_id}

    def _owned(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        doc = self._docs.get(doc_id)
        if doc is None or doc["owner"] != user:
            return None
        return doc

    def get_document(self, token, doc_id):
        user = self._auth(token)
        if user is None:
            return 401, None
        doc = self._owned(user, doc_id)
        if doc is None:
            return 404, None
        return 200, dict(doc)

    def update_document(self, token, doc_id, title, content):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not self._valid_doc_fields(title, content):
            return 400, None
        doc = self._owned(user, doc_id)
        if doc is None:
            return 404, None
        doc["title"] = title
        doc["content"] = content
        return 200, dict(doc)

    def delete_document(self, token, doc_id):
        user = self._auth(token)
        if user is None:
            return 401, None
        doc = self._owned(user, doc_id)
        if doc is None:
            return 404, None
        seq = self._doc_seq.pop(doc_id)
        del self._docs[doc_id]
        del self._user_docs[user][seq]
        return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not _is_int(page_size) or not 1 <= page_size <= 100:
            return 400, None
        last_seq = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                return 400, None
            entry = self._cursors.get(cursor)
            if entry is None or entry[0] != user:
                return 400, None
            last_seq = entry[1]
        remaining = [(s, d) for s, d in self._live_docs(user) if s > last_seq]
        page = remaining[:page_size]
        next_cursor = None
        if len(remaining) > page_size:
            next_cursor = secrets.token_hex(16)
            self._cursors[next_cursor] = (user, page[-1][0])
        return 200, {"items": [dict(d) for _, d in page], "next_cursor": next_cursor}

    def search_documents(self, token, query):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not isinstance(query, str) or query == "":
            return 400, None
        q = query.casefold()
        hits = [dict(d) for _, d in self._live_docs(user)
                if q in d["title"].casefold() or q in d["content"].casefold()]
        return 200, hits

    def export_documents(self, token):
        user = self._auth(token)
        if user is None:
            return 401, None
        return 200, [dict(d) for _, d in self._live_docs(user)]

    # ---- payments ----
    def pay(self, token, amount_cents, idempotency_key):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not _is_int(amount_cents) or not 1 <= amount_cents <= 1000000:
            return 400, None
        if not isinstance(idempotency_key, str) or idempotency_key == "":
            return 400, None
        key = (user, idempotency_key)
        attempt = self._attempts.get(key)
        if attempt is not None:
            if attempt["amount"] != amount_cents:
                return 409, None
            if attempt["payment"] is not None:
                return 200, dict(attempt["payment"])
        else:
            attempt = {"amount": amount_cents, "payment": None}
            self._attempts[key] = attempt
        reference = "%s:%s" % (user, idempotency_key)
        try:
            self._gateway.charge(reference, amount_cents)
        except GatewayTimeout:
            return 504, None
        self._next_payment += 1
        payment = {
            "id": "pay-%d" % self._next_payment,
            "amount_cents": amount_cents,
            "idempotency_key": idempotency_key,
            "created_at": self._clock.now(),
        }
        attempt["payment"] = payment
        self._payments.setdefault(user, []).append(payment)
        return 201, dict(payment)

    def list_payments(self, token):
        user = self._auth(token)
        if user is None:
            return 401, None
        return 200, [dict(p) for p in self._payments.get(user, [])]

