import pytest
from hypothesis import given, settings, strategies as st

from solution import Service


class FakeClock:
    def __init__(self, t=0.0):
        self.t = float(t)

    def now(self):
        return self.t


class FakeGateway:
    def charge(self, reference, amount_cents):
        return {"reference": reference}


FAST = settings(max_examples=40, deadline=None)


def make():
    return Service(FakeClock(), FakeGateway())


def logged_in(svc, name="alice", pw="password1"):
    assert svc.register(name, pw)[0] == 201
    s, b = svc.login(name, pw)
    assert s == 200, f"login output={(s, b)!r}"
    return b["token"]


# ---- M005: page_size 0 must be rejected ----

def test_page_size_zero_is_400_without_documents():
    """A page_size of 0 gives 400 even when the caller has no documents."""
    svc = make()
    tok = logged_in(svc)
    out = svc.list_documents(tok, 0)
    assert out[0] == 400, f"page_size=0 documents=0 output={out!r}"


def test_page_size_zero_is_400_with_documents():
    """A page_size of 0 gives 400 when the caller has documents."""
    svc = make()
    tok = logged_in(svc)
    for i in range(3):
        assert svc.create_document(tok, "t%d" % i, "c")[0] == 201
    try:
        out = svc.list_documents(tok, 0)
    except Exception as e:  # a crash is not the required 400
