import pytest
from hypothesis import given, settings, strategies as st

from solution import Service
from gateway import GatewayTimeout

SETTINGS = settings(max_examples=30, deadline=None)


class Clock:
    def __init__(self, t=1000.0):
        self.t = float(t)

    def now(self):
        return self.t


class FakeGateway:
    def __init__(self):
        self.charged = {}

    def charge(self, reference, amount_cents):
        self.charged.setdefault(reference, amount_cents)
        return {"status": "ok"}


def make():
    return Service(Clock(), FakeGateway(), token_ttl=3600)


NON_STR = [None, 12345678, 1.5, ["abcdef"], ("abc",), True]


def test_register_non_string_username_gives_400_and_creates_no_user():
    """A username that is not a 3-32 character string from [a-z0-9_] must give 400 rather than an error."""
    svc = make()
    for name in NON_STR:
        out = svc.register(name, "password1")
        assert isinstance(out, tuple) and out[0] == 400, f"input={(name, 'password1')!r} output={out!r}"
    out = svc.register("abc", "password1")
    assert out[0] == 201, f"input=('abc','password1') output={out!r}"


def test_register_non_string_password_gives_400_and_creates_no_user():
    """A password that is not a string of at least 8 characters must give 400 rather than an error."""
    svc = make()
    for pw in NON_STR:
        out = svc.register("valid_user", pw)
        assert isinstance(out, tuple) and out[0] == 400, f"input=('valid_user', {pw!r}) output={out!r}"
    out = svc.login("valid_user", "password1")
    assert out[0] == 401, f"input=('valid_user','password1') output={out!r}"
    out = svc.register("valid_user", "password1")
    assert out[0] == 201, f"input=('valid_user','password1') output={out!r}"


def test_register_both_non_string_gives_400():
    """When neither username nor password is a valid string, register gives 400."""
    svc = make()
    out = svc.register(None, None)
    assert out[0] == 400, f"input=(None, None) output={out!r}"
    out = svc.register(123, 456)
    assert out[0] == 400, f"input=(123, 456) output={out!r}"


@SETTINGS
@given(
    bad=st.one_of(st.none(), st.integers(), st.floats(allow_nan=False), st.lists(st.integers(), max_size=3)),
    good_name=st.text(alphabet="abcdefghijklmnopqrstuvwxyz0123456789_", min_size=3, max_size=32),
    good_pw=st.text(alphabet="abcdefgh12345678", min_size=8, max_size=20),
)
def test_register_with_one_invalid_non_string_argument_is_400(bad, good_name, good_pw):
    """For a non-string username or password paired with a valid other argument, register returns 400 and registers nobody."""
    svc = make()
    out = svc.register(bad, good_pw)
    assert out[0] == 400, f"input=({bad!r}, {good_pw!r}) output={out!r}"
    out = svc.register(good_name, bad)
    assert out[0] == 400, f"input=({good_name!r}, {bad!r}) output={out!r}"
    out = svc.login(good_name, good_pw)
    assert out[0] == 401, f"input=({good_name!r}, {good_pw!r}) output={out!r}"

