from hypothesis import given, settings, strategies as st


class FakeClock:
    def now(self):
        return 0.0


class FakeGateway:
    def charge(self, reference, amount_cents):
        return None


def make_service(Service):
    return Service(FakeClock(), FakeGateway())


def call_register(service, username, password):
    try:
        return service.register(username, password)
    except Exception as exc:  # A specified 400 response must not be replaced by an exception.
        return ("EXCEPTION", type(exc).__name__, repr(exc))


def assert_status(out, expected, inp):
    assert isinstance(out, tuple) and len(out) == 2 and out[0] == expected, (
        f"input={inp!r} output={out!r}"
    )


valid_username_st = st.text(
    alphabet=list("abcdefghijklmnopqrstuvwxyz0123456789_"),
    min_size=3,
    max_size=32,
)

non_string_st = st.one_of(
    st.none(),
    st.booleans(),
    st.integers(),
    st.floats(allow_nan=False, allow_infinity=False),
    st.lists(st.integers(), max_size=3),
    st.dictionaries(st.text(max_size=3), st.integers(), max_size=3),
)


@given(username=valid_username_st, password=non_string_st)
@settings(max_examples=40, deadline=None)
def test_register_rejects_non_string_password_with_400(username, password):
    """Registration must return 400 when the password is not a string satisfying the password requirement."""
    from solution import Service

    service = make_service(Service)
    out = call_register(service, username, password)
    assert_status(out, 400, ("register", username, password))


def test_register_rejects_non_string_username_with_400():
    """Registration must return 400 when the username is not a string satisfying the username requirement."""
    from solution import Service

    service = make_service(Service)
    username = 123
    password = "password123"
    out = call_register(service, username, password)
    assert_status(out, 400, ("register", username, password))
